+function limit(lines: string[], max?: number): string[] {
+  return max === undefined ? lines : lines.slice(0, max);
+}
+
+export function processStackString(
+  stack: string,
+  options: NormalizedErrorStackOptions
+): string {
+  let lines = stack.split('\
');
